package pe.edu.upeu.bomerp;
import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Component;import org.springframework.boot.CommandLineRunner;import org.springframework.transaction.annotation.Transactional;import lombok.RequiredArgsConstructor;import java.math.BigDecimal;import java.util.*;
import pe.edu.upeu.bomerp.administracion.model.*;import pe.edu.upeu.bomerp.administracion.repository.*;import pe.edu.upeu.bomerp.articulo.model.*;import pe.edu.upeu.bomerp.articulo.repository.*;import pe.edu.upeu.bomerp.personas.persona.entity.*;import pe.edu.upeu.bomerp.personas.persona.repository.PersonaRepository;import pe.edu.upeu.bomerp.produccion.model.*;import pe.edu.upeu.bomerp.produccion.repository.FormulaRepository;
@Component @Profile("demo") @RequiredArgsConstructor public class DemoData implements CommandLineRunner {
private final EmpresaRepository empresas;private final SucursalRepository sucursales;private final AlmacenRepository almacenes;private final UnidadMedidaRepository unidades;private final ArticuloRepository articulos;private final PersonaRepository personas;private final FormulaRepository formulas;
@Transactional public void run(String...args){if(empresas.count()>0)return;var e=new Empresa();e.setRuc("20123456789");e.setRazonSocial("Empresa demostrativa de producción y comercialización");empresas.save(e);var s=new Sucursal();s.setEmpresa(e);s.setNombre("Planta principal — demostración");sucursales.save(s);for(var nombre:List.of("Materias primas","Productos terminados")){var a=new Almacen();a.setSucursal(s);a.setNombre(nombre);a.setTipo(nombre.startsWith("Materias")?Almacen.TipoAlmacen.MATERIA_PRIMA:Almacen.TipoAlmacen.PRODUCTO_TERMINADO);almacenes.save(a);}var u=new UnidadMedida();u.setCodigo("KG");u.setNombre("Kilogramo");u.setSimbolo("kg");unidades.save(u);
for(var codigo:List.of("MAIZ-01","SOYA-01","PUR-001")){var a=new Articulo();a.setCodigo(codigo);a.setNombre(codigo.equals("PUR-001")?"Purina de engorde":codigo.equals("MAIZ-01")?"Maíz amarillo":"Harina de soya");a.setDescripcion("Artículo de demostración académica");a.setTipoArticulo(codigo.equals("PUR-001")?Articulo.TipoArticulo.PRODUCTO_TERMINADO:Articulo.TipoArticulo.MATERIA_PRIMA);a.setUnidadMedida(u);a.setCostoReferencial(new BigDecimal("2.50"));if(codigo.equals("PUR-001"))a.setPrecioVenta(new BigDecimal("4.50"));articulos.save(a);}for(var rol:List.of(RolPersona.PROVEEDOR,RolPersona.CLIENTE)){var p=new pe.edu.upeu.bomerp.personas.persona.entity.Persona();p.setTipoDocumento(TipoDocumento.RUC);p.setNumeroDocumento(rol==RolPersona.PROVEEDOR?"20999999991":"20999999992");p.setNombreORazonSocial(rol+" de demostración");p.setRoles(Set.of(rol));personas.save(p);}var f=new Formula();f.setNombre("Purina de engorde 60/40");f.setCodigoProductoTerminado("PUR-001");for(var codigo:List.of("MAIZ-01","SOYA-01")){var d=new FormulaDetalle();d.setCodigoArticulo(codigo);d.setUnidadMedida("KG");d.setCantidadPorUnidad(new BigDecimal(codigo.equals("MAIZ-01")?"0.6":"0.4"));f.agregarDetalle(d);}formulas.save(f);}
}
